// Получаем XML из предыдущей ноды
const xml = $input.first().json.data;

// Функция очистки текста
function cleanText(text) {
  if (!text) return "";
  // Убираем CDATA обертку если есть
  let cleaned = text.replace(/<!\[CDATA\[(.*?)\]\]>/, '$1');
  // Заменяем HTML сущности
  cleaned = cleaned.replace(/&amp;/g, '&')
                   .replace(/&lt;/g, '<')
                   .replace(/&gt;/g, '>')
                   .replace(/&quot;/g, '"')
                   .replace(/&apos;/g, "'");
  // Убираем лишние пробелы и переносы строк
  cleaned = cleaned.replace(/\s+/g, ' ').trim();
  return cleaned;
}

// Парсим заголовки и ссылки
const titles = [];
const links = [];
const descriptions = [];

// Ищем каждый <item> блок
const itemRegex = /<item>(.*?)<\/item>/gs;
let itemMatch;

while ((itemMatch = itemRegex.exec(xml)) !== null) {
  const item = itemMatch[1];

  // Вытаскиваем title
  const titleMatch = item.match(/<title>(.*?)<\/title>/);
  if (titleMatch) {
    let title = cleanText(titleMatch[1]);
    // Фильтруем мусор (BBC News app, рекламные ссылки)
    if (title && 
        title.length > 5 && 
        !title.includes('BBC News app') &&
        !title.includes('iplayer') &&
        !title.includes('sounds') &&
        titles.length < 12) {
      titles.push(title);

      // Вытаскиваем link
      const linkMatch = item.match(/<link>(.*?)<\/link>/);
      if (linkMatch) {
        links.push(linkMatch[1]);
      } else {
        links.push('');
      }
    }
  }
}

// Формируем ответ для Telegram (без Markdown, чтобы не было конфликтов)
let resultText = "📰 НОВОСТИ BBC\n\n";
if (titles.length === 0) {
  resultText += "❌ Не удалось найти новости.";
} else {
  for (let i = 0; i < titles.length; i++) {
    resultText += `${i+1}. ${titles[i]}\n`;
    if (links[i]) {
      resultText += `   ${links[i]}\n`;
    }
    resultText += "\n";
  }
  resultText += `✅ Найдено новостей: ${titles.length}`;
}

return [{
  json: {
    text: resultText,
    titles: titles,
    links: links
  }
}];

// Получаем текущие новости из предыдущей ноды (парсинга)
const currentData = $input.first().json;
const currentTitles = currentData.titles || [];

// Загружаем старые заголовки из глобальной переменной (хранятся в памяти workflow)
const oldTitles = $vars.oldTitles || [];

// Находим новые заголовки (которых не было раньше)
const newTitles = [];
const newLinks = [];

for (let i = 0; i < currentTitles.length; i++) {
  if (!oldTitles.includes(currentTitles[i])) {
    newTitles.push(currentTitles[i]);
    newLinks.push(currentData.links?.[i] || '');
  }
}

// Обновляем переменную для следующего запуска
$vars.oldTitles = currentTitles;

// Формируем текст для отправки (только если есть новые)
let resultText = "";
if (newTitles.length > 0) {
  resultText = "🆕 НОВЫЕ НОВОСТИ BBC\n\n";
  for (let i = 0; i < newTitles.length; i++) {
    resultText += `${i+1}. ${newTitles[i]}\n`;
    if (newLinks[i]) {
      resultText += `   🔗 ${newLinks[i]}\n`;
    }
    resultText += "\n";
  }
  resultText += `\n✅ Найдено новых: ${newTitles.length}`;
} else {
  resultText = "✅ Новых новостей нет.";
}

return [{
  json: {
    text: resultText,
    hasNew: newTitles.length > 0,
    newTitles: newTitles,
    newLinks: newLinks
  }
}];
